SELECT * FROM kb_document

    AND title LIKE CONCAT('%', #{title}, '%')
    AND status = #{status}
    AND create_by = #{createBy}

ORDER BY create_time DESC

mapper.update:
UPDATE kb_document
title = #{title}, content = #{content}, chunk_count = #{chunkCount}, status = #{status}, update_time = sysdate()
WHERE id = #{id}
